            }
            if (commitTemplate.InvoiceScheduleOption.IsSet)
            {
                writer.WritePropertyName("invoice_schedule");
                JsonSerializer.Serialize(writer, commitTemplate.InvoiceSchedule, jsonSerializerOptions);
            }
            if (commitTemplate.DescriptionOption.IsSet)
                writer.WriteString("description", commitTemplate.Description);

            if (commitTemplate.RolloverFractionOption.IsSet)
                writer.WriteNumber("rollover_fraction", commitTemplate.RolloverFractionOption.Value!.Value);

            if (commitTemplate.ApplicableProductIdsOption.IsSet)
